recipes.snippet:
Rails 8.x (Propshaft; with Sprockets add consent.js/consent.css to app/assets/config/manifest.js). Needs the headers recipe. With 'strict-dynamic' a host/'self' source is ignored, so the external consent.js tag needs the nonce (`nonce: true`); the Google tag it creates inherits trust from it. `stylesheet_link_tag :app` already includes app/assets/stylesheets/consent.css. List the first-party cookie `consent` in essentialCookies. In config/initializers/content_security_policy.rb allow the beacons only in connect-src / img-src (never in script-src): `policy.connect_src :self, "https://www.google-analytics.com", "https://*.google-analytics.com", "https://*.analytics.google.com", "https://www.googletagmanager.com"` and `policy.img_src :self, :data, "https://www.google-analytics.com"`.
### file: app/views/shared/_consent.html.erb
<div id="consent-banner" role="dialog" aria-label="Cookie consent" hidden>
  <p>We use analytics cookies only if you accept. <a href="/privacy">Privacy notice</a></p>
  <button type="button" class="consent-btn" data-consent="granted">Accept all</button>
  <button type="button" class="consent-btn" data-consent="denied">Reject all</button>
</div>
<button type="button" id="consent-reopen" class="consent-link" hidden>Cookie settings</button>
<%= javascript_include_tag "consent", nonce: true, defer: true %>
### file: app/views/layouts/application.html.erb
<%# just before </body>: %>
<%= render "shared/consent" %>
### file: app/assets/javascripts/consent.js
(function () {
  var TAG_ID = 'G-XXXXXXXXXX'; // your Google tag ID
  var NONCE = (document.currentScript && document.currentScript.nonce) || '';
  var w = window;
  w.dataLayer = w.dataLayer || [];
  function gtag() { w.dataLayer.push(arguments); }
  var TYPES = ['ad_storage', 'analytics_storage', 'ad_user_data', 'ad_personalization'];
  function state(v) { var o = {}; TYPES.forEach(function (t) { o[t] = v; }); return o; }
  gtag('consent', 'default', state('denied')); // before any Google tag request
  function stored() { var m = document.cookie.match(/(?:^|; )consent=(granted|denied)/); return m ? m[1] : null; }
  function store(v) {
    document.cookie = 'consent=' + v + '; Max-Age=31536000; Path=/; SameSite=Lax' + (location.protocol === 'https:' ? '; Secure' : '');
  }
  var loaded = false;
  function loadTag() {
    if (loaded) return;
    loaded = true;
    var s = document.createElement('script');
    s.async = true;
    if (NONCE) s.nonce = NONCE;
    s.src = 'https://www.googletagmanager.com/gtag/js?id=' + encodeURIComponent(TAG_ID);
    document.head.appendChild(s);
    gtag('js', new Date());
    gtag('config', TAG_ID);
  }
  function apply(v) {
    if (v === 'granted') { gtag('consent', 'update', state('granted')); loadTag(); }
    else gtag('consent', 'update', state('denied'));
  }
  var banner = document.getElementById('consent-banner');
  var reopen = document.getElementById('consent-reopen');
  function show(on) { if (banner) banner.hidden = !on; if (reopen) reopen.hidden = on; }
  document.addEventListener('click', function (e) {
    var t = e.target;
    var b = t && t.closest ? t.closest('[data-consent]') : null;
    if (b) { var v = b.getAttribute('data-consent'); store(v); apply(v); show(false); }
    else if (t && t.closest && t.closest('#consent-reopen')) show(true);
  });
  var prior = stored();
  if (prior) { apply(prior); show(false); }
  else { if (navigator.globalPrivacyControl === true) apply('denied'); show(true); }
})();
### file: app/assets/stylesheets/consent.css
/* Accept and Reject get identical size, weight and contrast (PRV-002: no dark pattern). */
#consent-banner { position: fixed; inset: auto 0 0 0; padding: 1rem; background: #fff; color: #111; border-top: 1px solid #ccc; }
.consent-btn { font: inherit; font-weight: 600; padding: 0.6rem 1.2rem; margin-right: 0.5rem; background: #111; color: #fff; border: 2px solid #111; }
/* keep [hidden] effective: author display rules above must not override it */
#consent-banner[hidden], #consent-reopen[hidden] { display: none; }
